package com.zajel.app;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.net.Uri;import android.provider.OpenableColumns;import android.view.*;import android.widget.*;import com.zajel.app.core.*;import com.zajel.app.data.*;import com.zajel.app.domain.*;import java.util.*;
public final class MainActivity extends Activity {private static final int PICK_FILE=41;LinearLayout root;EditText email,password;AppContainer c;TextView status;Conversation active;ListView messageList;
 public void onCreate(Bundle b){super.onCreate(b);c=((ZajelApplication)getApplication()).container();if(c.auth.current()!=null)showHome();else showAuth();}
 TextView title(String s){TextView v=new TextView(this);v.setText(s);v.setTextSize(26);v.setTextColor(Color.rgb(24,45,61));v.setPadding(0,0,0,28);return v;}void base(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(40,70,40,30);root.setBackgroundColor(Color.WHITE);setContentView(root);}
 void showAuth(){base();root.addView(title("Zajel"));email=new EditText(this);email.setHint("Email");password=new EditText(this);password.setHint("Password");password.setInputType(129);root.addView(email);root.addView(password);Button in=new Button(this);in.setText("Sign in");Button up=new Button(this);up.setText("Create account");root.addView(in);root.addView(up);status=new TextView(this);root.addView(status);in.setOnClickListener(v->auth(false));up.setOnClickListener(v->auth(true));}
 void auth(boolean signup){status.setText("Connecting…");AuthRepository.Callback<UserSession> cb=new AuthRepository.Callback<UserSession>(){public void success(UserSession s){runOnUiThread(()->showHome());}public void error(Exception e){runOnUiThread(()->status.setText(e.getMessage()));}};if(signup)c.auth.signUp(email.getText().toString().trim(),password.getText().toString(),cb);else c.auth.signIn(email.getText().toString().trim(),password.getText().toString(),cb);}
 void showHome(){base();root.addView(title("Home"));TextView h=new TextView(this);h.setText("Your conversations");root.addView(h);ListView list=new ListView(this);root.addView(list,new LinearLayout.LayoutParams(-1,0,1));status=new TextView(this);root.addView(status);Button profile=new Button(this);profile.setText("Profile and settings");root.addView(profile);profile.setOnClickListener(v->showProfile());c.chats.conversations(new ChatRepository.Callback<List<Conversation>>(){public void success(List<Conversation> x){runOnUiThread(()->{status.setText(x.isEmpty()?"No conversations yet":"");String[] a=new String[x.size()];for(int i=0;i<x.size();i++)a[i]=x.get(i).title;list.setAdapter(new ArrayAdapter<String>(MainActivity.this,android.R.layout.simple_list_item_1,a));list.setOnItemClickListener((p,v,pos,id)->showChat(x.get(pos)));});}public void error(Exception e){runOnUiThread(()->status.setText(e.getMessage()));}});}
 void showChat(Conversation x){active=x;base();root.addView(title(x.title));messageList=new ListView(this);root.addView(messageList,new LinearLayout.LayoutParams(-1,0,1));LinearLayout bar=new LinearLayout(this);EditText input=new EditText(this);input.setHint("Message");Button send=new Button(this);send.setText("Send");Button file=new Button(this);file.setText("File");bar.addView(input,new LinearLayout.LayoutParams(0,-2,1));bar.addView(file);bar.addView(send);root.addView(bar);status=new TextView(this);root.addView(status);Button back=new Button(this);back.setText("Back to Home");root.addView(back);back.setOnClickListener(v->showHome());send.setOnClickListener(v->{String text=input.getText().toString().trim();if(!text.isEmpty()){send.setEnabled(false);c.chats.sendText(x.id,text,new ChatRepository.Callback<Message>(){public void success(Message m){runOnUiThread(()->{input.setText("");send.setEnabled(true);loadMessages();});}public void error(Exception e){runOnUiThread(()->{send.setEnabled(true);status.setText(e.getMessage());});}});}});file.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");startActivityForResult(i,PICK_FILE);});loadMessages();}
 void loadMessages(){c.chats.messages(active.id,new ChatRepository.Callback<List<Message>>(){public void success(List<Message> x){runOnUiThread(()->{String[] a=new String[x.size()];for(int i=0;i<x.size();i++){Message m=x.get(i);a[i]=m.attachment==null?m.body:"["+m.attachment.name+"]";}messageList.setAdapter(new ArrayAdapter<String>(MainActivity.this,android.R.layout.simple_list_item_1,a));});}public void error(Exception e){runOnUiThread(()->status.setText(e.getMessage()));}});}
 protected void onActivityResult(int r,int code,Intent d){super.onActivityResult(r,code,d);if(r!=PICK_FILE||code!=RESULT_OK||d==null||active==null)return;Uri u=d.getData();String name="attachment";String mime=getContentResolver().getType(u);c.chats.sendAttachment(active.id,u,name,mime,new ChatRepository.Callback<Message>(){public void success(Message m){runOnUiThread(()->{status.setText("File sent");loadMessages();});}public void error(Exception e){runOnUiThread(()->status.setText(e.getMessage()));}});}
 void showProfile(){base();root.addView(title("Your profile"));EditText user=new EditText(this);user.setHint("Username");EditText name=new EditText(this);name.setHint("Display name");EditText avatar=new EditText(this);avatar.setHint("Avatar URL");root.addView(user);root.addView(name);root.addView(avatar);Button save=new Button(this);save.setText("Save profile");Button out=new Button(this);out.setText("Sign out");root.addView(save);root.addView(out);status=new TextView(this);root.addView(status);c.profiles.get(new ProfileRepository.Callback<Profile>(){public void success(Profile p){runOnUiThread(()->{user.setText(p.username);name.setText(p.displayName);avatar.setText(p.avatarUrl);});}public void error(Exception e){runOnUiThread(()->status.setText(e.getMessage()));}});save.setOnClickListener(v->c.profiles.update(user.getText().toString(),name.getText().toString(),avatar.getText().toString(),new ProfileRepository.Callback<Profile>(){public void success(Profile p){runOnUiThread(()->status.setText("Profile saved"));}public void error(Exception e){runOnUiThread(()->status.setText(e.getMessage()));}}));out.setOnClickListener(v->{c.auth.signOut();showAuth();});}
}
